                paths = load_media_paths()
                if not paths:
                    _scan_state['last'] = {'error': 'Медиа пути пусты'}
                    return
                scanner = MediaScanner(_db(), paths)
                scanner.scan_all()
                _scan_state['last'] = {'success': True}
            except Exception as ex:
                _scan_state['last'] = {'error': str(ex)}
