# -*- coding: utf-8 -*-
"""Менеджер API ключей Gemini. Все данные хранятся в gemini_keys.json."""

import json
import time
from datetime import datetime, timezone
from pathlib import Path

from src.logger import logger

_KEYS_FILE = Path(__file__).parent / 'gemini_keys.json'
_DAY_SECONDS = 86400


def _load() -> dict:
    if _KEYS_FILE.exists():
        try:
            return json.loads(_KEYS_FILE.read_text(encoding='utf-8'))
        except Exception:
            pass
    return {}


def _save(data: dict) -> None:
    _KEYS_FILE.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding='utf-8')


def _now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


def _iso_to_ts(iso: str) -> float:
    try:
        return datetime.fromisoformat(iso).timestamp()
    except Exception:
        return 0.0


def load_api_keys(names: list = None) -> tuple[list, list, list]:
    """
    Возвращает (api_keys, key_names, key_names) отсортированные по last_run (самый ранний первый).
    Фильтрует: только status == 'active' и не забаненные (дневная квота).
    names — опциональный список имён; если None — берёт все из файла.
    """
    data = _load()
    now = time.time()

    candidates = []
    for name, entry in data.items():
        if names and name not in names:
            continue
        if entry.get('status') != 'active':
            continue
        exhausted_at = entry.get('exhausted_at')
        if exhausted_at:
            elapsed = now - _iso_to_ts(exhausted_at)
            if elapsed < _DAY_SECONDS:
                remaining = _DAY_SECONDS - elapsed
                h, m = divmod(int(remaining), 3600)
                m //= 60
                # logger.debug(f"Daily quota exhausted for {name}: unlocks in {h}h {m}m")  # suppressed debug output
                continue
            else:
                # Бан истёк — снимаем
                del entry['exhausted_at']
                _save(data)

        last_run = _iso_to_ts(entry.get('last_run', '2000-01-01T00:00:00Z'))
        candidates.append((last_run, name, entry['api_key']))

    # Сортируем: самый давно использованный — первый
    candidates.sort(key=lambda x: x[0])

    api_keys = [c[2] for c in candidates]
    key_names = [c[1] for c in candidates]
    return api_keys, key_names, key_names


def mark_exhausted(key_name: str) -> None:
    """Помечает ключ как исчерпавший дневную квоту."""
    data = _load()
    if key_name in data:
        data[key_name]['exhausted_at'] = _now_iso()
        _save(data)


def update_last_run(key_name: str) -> None:
    """Обновляет время последнего использования ключа."""
    data = _load()
    if key_name in data:
        data[key_name]['last_run'] = _now_iso()
        _save(data)


def next_available_in(names: list = None) -> float:
    """Возвращает секунды до разблокировки ближайшего ключа. 0 если нет забаненных."""
    data = _load()
    now = time.time()
    min_remaining = 0.0
    for name, entry in data.items():
        if names and name not in names:
            continue
        if entry.get('status') != 'active':
            continue
        exhausted_at = entry.get('exhausted_at')
        if not exhausted_at:
            continue
        elapsed = now - _iso_to_ts(exhausted_at)
        remaining = _DAY_SECONDS - elapsed
        if remaining > 0:
            if min_remaining == 0.0 or remaining < min_remaining:
                min_remaining = remaining
    return min_remaining


def reset_exhausted(names: list = None) -> None:
    """Принудительный сброс дневной квоты у ключей."""
    data = _load()
    targets = names if names else list(data.keys())
    for name in targets:
        if name in data and 'exhausted_at' in data[name]:
            del data[name]['exhausted_at']
            print(f"  ✅ {name} — квота сброшена")
        else:
            print(f"  ℹ️  {name} — квота не была установлена")
    _save(data)


def get_status(names: list = None) -> None:
    """Выводит статус всех ключей."""
    data = _load()
    now = time.time()
    print("[API KEY STATUS]")
    items = {k: v for k, v in data.items() if not names or k in names}
    for name, entry in items.items():
        status = entry.get('status', '?')
        last_run = entry.get('last_run', '—')
        exhausted_at = entry.get('exhausted_at')
        if exhausted_at:
            elapsed = now - _iso_to_ts(exhausted_at)
            if elapsed < _DAY_SECONDS:
                remaining = _DAY_SECONDS - elapsed
                h, m = divmod(int(remaining), 3600)
                m //= 60
                print(f"  ⛔ {name} [{status}] — дневная квота, разблокировка через {h}ч {m}м")
                continue
        if status == 'active':
            print(f"  ✅ {name} — last_run: {last_run}")
        else:
            print(f"  🚫 {name} [{status}]")

